function shell(title,content){return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><title>${escapeText(title)} · Cộng đồng PINO</title><style>${STYLE}</style></head><body><div class="app"><header class="head"><a class="logo" href="/community" aria-label="PINO Space">PINO<small>SPACE</small></a><a class="pill" href="/community">Cộng đồng</a></header><main class="content">${content}</main><footer class="foot"><a href="/community">⌂ Cộng đồng công khai</a></footer></div></body></html>`;}

function renderIndex(){const items=POSTS.map(p=>`<a class="item" href="/post/${encodeURIComponent(p.id)}" data-public-post="${escapeText(p.id)}"><div class="pic">${p.svgs[0]}${p.type==="reel"?"<span>▶</span>":""}</div><div class="info"><strong>${escapeText(p.alias)}</strong><b>${escapeText(p.title)}</b><small>${p.app==="piano"?"Piano":"Hội Họa"} · ${escapeText(p.date)}</small><p>${escapeText(p.caption)}</p></div></a>`).join("");return shell("Cộng đồng PINO",`<h1 class="title">Cộng đồng PINO</h1><p class="lead">Những tác phẩm đã được chia sẻ công khai. Không cần đăng nhập.</p><div data-public-feed>${items}</div><p class="demo">Bản minh họa · không chứa nội dung học viên thật.</p>`);}

function renderPost(p){const comments=p.comments.map(c=>`<p><strong>${escapeText(c.author)}</strong>${escapeText(c.body)}</p>`).join("");const media=p.type==="reel"?`<div class="media"><video controls playsinline muted preload="metadata" src="/video/${p.app==="piano"?"piano-demo":"art-demo"}.mp4" aria-label="Video minh họa ${escapeText(p.title)}"></video><small class="synthetic">Clip đồ họa tổng hợp, không phải video học viên.</small></div>`:`<div class="photo" data-carousel><div class="slides">${p.svgs.map((svg,i)=>`<div class="slide" aria-hidden="${i!==0}">${svg}</div>`).join("")}</div><span class="count" data-count>1/${p.svgs.length}</span><button class="arrow prev" data-prev aria-label="Ảnh trước">‹</button><button class="arrow next" data-next aria-label="Ảnh tiếp">›</button><div class="dots">${p.svgs.map((_,i)=>`<button class="dot" data-to="${i}" aria-label="Đến ảnh ${i+1}" aria-current="${i===0}"></button>`).join("")}</div></div>`;
const js=p.type==="photo"?`<script>(function(){const root=document.querySelector('[data-carousel]');if(!root)return;const strip=root.querySelector('.slides'),dots=[...root.querySelectorAll('[data-to]')];let i=0,x=null;const set=n=>{i=Math.min(dots.length-1,Math.max(0,n));strip.style.transform='translateX(-'+(i*100)+'%)';root.querySelector('[data-count]').textContent=(i+1)+'/'+dots.length;root.querySelector('[data-prev]').disabled=i===0;root.querySelector('[data-next]').disabled=i===dots.length-1;dots.forEach((d,k)=>d.setAttribute('aria-current',String(k===i)))};root.querySelector('[data-prev]').onclick=()=>set(i-1);root.querySelector('[data-next]').onclick=()=>set(i+1);dots.forEach((d,k)=>d.onclick=()=>set(k));root.ontouchstart=e=>{x=e.changedTouches[0]?.clientX};root.ontouchend=e=>{if(x===null)return;const dx=(e.changedTouches[0]?.clientX??x)-x;x=null;if(Math.abs(dx)>36)set(i+(dx<0?1:-1))};root.onkeydown=e=>{if(e.key==='ArrowRight')set(i+1);if(e.key==='ArrowLeft')set(i-1)};set(0)})();</script>`:"";
return shell(p.title,`<article class="detail" data-public-detail="${escapeText(p.id)}"><a class="back" href="/community" aria-label="Về Cộng đồng công khai">‹ Về Cộng đồng</a><div class="author"><strong>${escapeText(p.alias)}</strong><small>${p.app==="piano"?"Piano":"Hội Họa"} · ${escapeText(p.date)}</small></div>${media}<div class="body"><h1>${escapeText(p.title)}</h1><p class="caption" data-public-caption>${escapeText(p.caption)}</p><section class="comments" aria-label="Bình luận"><h2>Bình luận (${p.comments.length})</h2>${comments}</section></div><a class="again" href="/community">Xem các bài Cộng đồng khác</a></article>${js}`);}

function videoResponse(req,key){const encoded=VIDEOS[key];if(!encoded)return new Response("Not Found",{status:404,headers:headers()});const binary=atob(encoded),len=binary.length;let start=0,end=len-1,status=200;const range=req.headers.get("Range");if(range){const match=/^bytes=(\d+)-(\d*)$/.exec(range);if(!match)return new Response(null,{status:416,headers:{"Content-Range":"bytes */"+len}});start=Number(match[1]);end=match[2]?Number(match[2]):end;if(start>=len||end<start)return new Response(null,{status:416,headers:{"Content-Range":"bytes */"+len}});end=Math.min(end,len-1);status=206;}const bytes=Uint8Array.from(binary.slice(start,end+1),c=>c.charCodeAt(0));const h={"Content-Type":"video/mp4","Content-Length":String(bytes.length),"Accept-Ranges":"bytes","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"};if(status===206)h["Content-Range"]="bytes "+start+"-"+end+"/"+len;return new Response(req.method==="HEAD"?null:bytes,{status,headers:h});}

async function handleFetch(req){if(req.method!=="GET"&&req.method!=="HEAD")return new Response("Method Not Allowed",{status:405,headers:headers()});const u=new URL(req.url),path=u.pathname;if(path==="/favicon.ico")return new Response(null,{status:204,headers:{"Cache-Control":"public,max-age=86400"}});let response;if(path==="/"||path==="/community"||path==="/piner/public/community"){response=new Response(renderIndex(),{status:200,headers:headers()});}else{const match=/^\/(?:piner\/public\/)?post\/([a-z0-9-]+)$/.exec(path);if(match){const p=POSTS.find(x=>x.id===match[1]);response=p?new Response(renderPost(p),{status:200,headers:headers()}):new Response(shell("Không tìm thấy",'<div class="publicError">Không tìm thấy bài đăng công khai.</div>'),{status:404,headers:headers()});}else{const video=/^\/(?:video|piner\/media)\/(art-demo|piano-demo)\.mp4$/.exec(path);response=video?videoResponse(req,video[1]):new Response("Not Found",{status:404,headers:headers()});}}return req.method==="HEAD"?new Response(null,{status:response.status,headers:response.headers}):response;}

